{
  "themes": [
    {
      "cluster": 24,
      "name": "Purchased Music Missing After Subscription Cancel",
      "description": "Customers report that songs or albums they bought disappear when they cancel or change their Apple Music subscription."
    },
    {
      "cluster": 25,
      "name": "Unexpected Apple Music Subscription Charges",
      "description": "Users are being billed multiple times or incorrectly for Apple Music, often despite having a student plan."
    },
    {
      "cluster": 26,
      "name": "Mail App Deleting/Notification Failures on iOS 11",
      "description": "iOS 11 updates cause mail notifications to lag and prevent deleting emails, leading to app freezes."
    },
    {
      "cluster": 27,
      "name": "Alarms Not Sounding After Snooze or Silent Mode",
      "description": "Alarms fail to ring or vibrate after being snoozed or when the device is in silent mode, leaving users late."
    },
    {
      "cluster": 28,
      "name": "Volume and Sound Distortion Issues Post‑Update",
      "description": "After updating, users experience low volume, missing ringtones, or distorted audio during calls and media playback."
    },
    {
      "cluster": 29,
      "name": "Headphone/Adapter Failure After Short Use",
      "description": "Built‑in headphones, adapters, or earbuds stop working or produce crackling sounds shortly after purchase."
    },
    {
      "cluster": 30,
      "name": "General Help Requests Without Specific Issue",
      "description": "Customers post vague pleas for assistance or explanations without describing a concrete problem."
    },
    {
      "cluster": 31,
      "name": "Frequent Glitch Fix Requests",
      "description": "Users repeatedly ask for bugs and glitches to be fixed, often without detailing the exact malfunction."
    },
    {
      "cluster": 32,
      "name": "Autocorrect Changing Letter “I” to Symbols",
      "description": "The keyboard incorrectly replaces the letter “I” with odd symbols or other characters after an update."
    },
    {
      "cluster": 33,
      "name": "Keyboard Layout and Compatibility Problems",
      "description": "Issues with missing keys, non‑working smart keyboards, and lack of numeric keypads on iPad/iPhone keyboards."
    },
    {
      "cluster": 34,
      "name": "Negative Reactions to Recent iOS Updates",
      "description": "Customers express frustration and request fixes for problems introduced by the latest iOS updates."
    },
    {
      "cluster": 35,
      "name": "Contacts Data Corruption After Update",
      "description": "Contacts disappear, names are removed, or contact info is scrambled following system updates."
    }
  ]
}
